1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	/** Initial assessment surcharge on a customer's first insurance. */
15	const FIRST_INSURANCE_RATE = 0.1;
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Step = {
23	  op: string;
24	  items: Item[];
25	};
26	
27	export type Item = { type: string } & Record<string, unknown>;
28	
29	export type Result = { premium: number };
30	
31	export type ScenarioOutcome = { results: Result[] };
32	
33	/** Special base premium for a building block of 3 alike components. */
34	const BLOCK_BASE_PREMIUM = 60;
35	
36	/** Sum of the base premiums of every item on a policy. */
37	const calculateBasePremium = (items: Item[]): number => {
38	  if (items.length === 3 && items.every((item) => item.type === items[0].type)) {
39	    return BLOCK_BASE_PREMIUM;
40	  }
41	  return items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
42	};
43	
44	/** Premiums are rounded up — fractions of a gold piece fall to MHPCO. */
45	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
46	
47	/** Price a policy covering the given items. */
48	const quotePremium = (items: Item[]): number => {
49	  const policyBasePremium = calculateBasePremium(items);
50	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
51	  return roundPremiumUp(
52	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
53	  );
54	};
55	
56	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
57	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
58	});
