/** A block is exactly this many components of one and the same type. */
const BLOCK_SIZE = 3;

/** Special base premium charged for a complete block, instead of the per-item sum. */
const BLOCK_BASE_PREMIUM = 60;

/** True when the items form a complete block: exactly 3, all of the same type. */
const formsBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE &&
  items.every((item) => item.type === items[0].type);

/** Sum of the base premiums of the given items, charged individually. */
const sumItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);

/** Base premium of a policy covering the given items. */
const calculateBasePremium = (items: Item[]): number =>
  formsBlock(items) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(items);
